import React, { useRef, useEffect, useState } from 'react';
import { WebRTCService } from '../services/webrtc';

interface VideoPlayerProps {
  streamId: string;
  isLocal?: boolean;
  onStreamEnd?: () => void;
}

const VideoPlayer: React.FC<VideoPlayerProps> = ({ 
  streamId, 
  isLocal = false, 
  onStreamEnd 
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const initializeStream = async () => {
      try {
        const stream = await WebRTCService.getStream(streamId);
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
        }
      } catch (err) {
        setError('Failed to load video stream');
        console.error('Video stream error:', err);
      }
    };

    initializeStream();
  }, [streamId]);

  return (
    <div className="video-player">
      <video
        ref={videoRef}
        autoPlay={isLocal}
        muted={isLocal}
        playsInline
        onPlay={() => setIsPlaying(true)}
        onPause={() => setIsPlaying(false)}
        onEnded={onStreamEnd}
      />
      {error && <div className="error">{error}</div>}
    </div>
  );
};

export default VideoPlayer;

import { io, Socket } from 'socket.io-client';

class WebRTCService {
  private socket: Socket;
  private localStream: MediaStream | null = null;
  private peerConnections: Map<string, RTCPeerConnection> = new Map();
  private configuration: RTCConfiguration = {
    iceServers: [
      { urls: 'stun:stun.l.google.com:19302' },
      { urls: 'stun:stun1.l.google.com:19302' }
    ]
  };

  constructor() {
    this.socket = io(process.env.REACT_APP_SOCKET_URL || 'http://localhost:3001');
    this.setupSocketListeners();
  }

  private setupSocketListeners() {
    this.socket.on('offer', this.handleOffer.bind(this));
    this.socket.on('answer', this.handleAnswer.bind(this));
    this.socket.on('ice-candidate', this.handleIceCandidate.bind(this));
    this.socket.on('user-disconnected', this.handleUserDisconnected.bind(this));
  }

  async getLocalStream(constraints: MediaStreamConstraints = { video: true, audio: true }) {
    try {
      this.localStream = await navigator.mediaDevices.getUserMedia(constraints);
      return this.localStream;
    } catch (error) {
      console.error('Error accessing media devices:', error);
      throw error;
    }
  }

  async createPeerConnection(userId: string): Promise<RTCPeerConnection> {
    const pc = new RTCPeerConnection(this.configuration);
    this.peerConnections.set(userId, pc);

    // Add local stream tracks to peer connection
    if (this.localStream) {
      this.localStream.getTracks().forEach(track => {
        pc.addTrack(track, this.localStream!);
      });
    }

    // Handle incoming stream
    pc.ontrack = (event) => {
      const [remoteStream] = event.streams;
      this.onRemoteStream?.(remoteStream, userId);
    };

    // Handle ICE candidates
    pc.onicecandidate = (event) => {
      if (event.candidate) {
        this.socket.emit('ice-candidate', {
          candidate: event.candidate,
          targetUserId: userId
        });
      }
    };

    return pc;
  }

  private async handleOffer(data: { offer: RTCSessionDescriptionInit; fromUserId: string }) {
    const pc = await this.createPeerConnection(data.fromUserId);
    await pc.setRemoteDescription(data.offer);
    const answer = await pc.createAnswer();
    await pc.setLocalDescription(answer);

    this.socket.emit('answer', {
      answer,
      targetUserId: data.fromUserId
    });
  }

  private async handleAnswer(data: { answer: RTCSessionDescriptionInit; fromUserId: string }) {
    const pc = this.peerConnections.get(data.fromUserId);
    if (pc) {
      await pc.setRemoteDescription(data.answer);
    }
  }

  private async handleIceCandidate(data: { candidate: RTCIceCandidateInit; fromUserId: string }) {
    const pc = this.peerConnections.get(data.fromUserId);
    if (pc) {
      await pc.addIceCandidate(data.candidate);
    }
  }

  private handleUserDisconnected(userId: string) {
    const pc = this.peerConnections.get(userId);
    if (pc) {
      pc.close();
      this.peerConnections.delete(userId);
    }
  }

  onRemoteStream?: (stream: MediaStream, userId: string) => void;

  disconnect() {
    this.peerConnections.forEach(pc => pc.close());
    this.peerConnections.clear();
    if (this.localStream) {
      this.localStream.getTracks().forEach(track => track.stop());
    }
    this.socket.disconnect();
  }
}

export default new WebRTCService();

import { useState, useEffect, useRef } from 'react';

interface UseMediaStreamOptions {
  video?: boolean | MediaTrackConstraints;
  audio?: boolean | MediaTrackConstraints;
}

export const useMediaStream = (options: UseMediaStreamOptions = {}) => {
  const [stream, setStream] = useState<MediaStream | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const streamRef = useRef<MediaStream | null>(null);

  const startStream = async () => {
    setIsLoading(true);
    setError(null);

    try {
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: options.video ?? true,
        audio: options.audio ?? true
      });

      streamRef.current = mediaStream;
      setStream(mediaStream);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to access media devices';
      setError(errorMessage);
      console.error('Media stream error:', err);
    } finally {
      setIsLoading(false);
    }
  };

  const stopStream = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => {
        track.stop();
      });
      streamRef.current = null;
      setStream(null);
    }
  };

  useEffect(() => {
    return () => {
      stopStream();
    };
  }, []);

  return {
    stream,
    error,
    isLoading,
    startStream,
    stopStream
  };
};

