import { Request, Response } from 'express';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import { User } from '../models/User';
import { validationResult } from 'express-validator';
import { AppError } from '../utils/AppError';
import { catchAsync } from '../utils/catchAsync';
import { sendEmail } from '../utils/email';
import crypto from 'crypto';

const signToken = (id: string) => {
  return jwt.sign({ id }, process.env.JWT_SECRET!, {
    expiresIn: process.env.JWT_EXPIRES_IN || '7d',
  });
};

const createSendToken = (user: any, statusCode: number, res: Response) => {
  const token = signToken(user._id);
  const cookieOptions = {
    expires: new Date(
      Date.now() + (Number(process.env.JWT_COOKIE_EXPIRES_IN) || 7) * 24 * 60 * 60 * 1000
    ),
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'strict' as const,
  };

  res.cookie('jwt', token, cookieOptions);

  // Remove password from output
  user.password = undefined;

  res.status(statusCode).json({
    status: 'success',
    token,
    data: {
      user,
    },
  });
};

export const signup = catchAsync(async (req: Request, res: Response) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'fail',
      message: 'Validation failed',
      errors: errors.array(),
    });
  }

  const { name, email, password, passwordConfirm } = req.body;

  // Check if user already exists
  const existingUser = await User.findOne({ email });
  if (existingUser) {
    throw new AppError('User with this email already exists', 400);
  }

  // Create new user
  const newUser = await User.create({
    name,
    email,
    password,
    passwordConfirm,
  });

  // Generate email verification token
  const verificationToken = newUser.createEmailVerificationToken();
  await newUser.save({ validateBeforeSave: false });

  // Send verification email
  try {
    const verificationUrl = `${req.protocol}://${req.get(
      'host'
    )}/api/v1/auth/verify-email/${verificationToken}`;

    await sendEmail({
      email: newUser.email,
      subject: 'Email Verification - Mobile API',
      template: 'emailVerification',
      data: {
        name: newUser.name,
        verificationUrl,
      },
    });

    res.status(201).json({
      status: 'success',
      message: 'User registered successfully. Please check your email to verify your account.',
    });
  } catch (err) {
    newUser.emailVerificationToken = undefined;
    newUser.emailVerificationExpires = undefined;
    await newUser.save({ validateBeforeSave: false });

    throw new AppError('Error sending email. Please try again later.', 500);
  }
});

export const login = catchAsync(async (req: Request, res: Response) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      status: 'fail',
      message: 'Validation failed',
      errors: errors.array(),
    });
  }

  const { email, password } = req.body;

  // Check if user exists and password is correct
  const user = await User.findOne({ email }).select('+password');
  if (!user || !(await user.correctPassword(password, user.password))) {
    throw new AppError('Incorrect email or password', 401);
  }

  // Check if email is verified
  if (!user.emailVerified) {
    throw new AppError('Please verify your email before logging in', 401);
  }

  // Check if account is active
  if (!user.active) {
    throw new AppError('Your account has been deactivated', 401);
  }

  // Update last login
  user.lastLogin = new Date();
  await user.save({ validateBeforeSave: false });

  createSendToken(user, 200, res);
});

export const logout = (req: Request, res: Response) => {
  res.cookie('jwt', 'loggedout', {
    expires: new Date(Date.now() + 10 * 1000),
    httpOnly: true,
  });
  res.status(200).json({ status: 'success' });
};

export const forgotPassword = catchAsync(async (req: Request, res: Response) => {
  const { email } = req.body;

  const user = await User.findOne({ email });
  if (!user) {
    throw new AppError('No user found with that email address', 404);
  }

  const resetToken = user.createPasswordResetToken();
  await user.save({ validateBeforeSave: false });

  try {
    const resetUrl = `${req.protocol}://${req.get(
      'host'
    )}/api/v1/auth/reset-password/${resetToken}`;

    await sendEmail({
      email: user.email,
      subject: 'Password Reset - Mobile API',
      template: 'passwordReset',
      data: {
        name: user.name,
        resetUrl,
        resetToken,
      },
    });

    res.status(200).json({
      status: 'success',
      message: 'Token sent to email!',
    });
  } catch (err) {
    user.passwordResetToken = undefined;
    user.passwordResetExpires = undefined;
    await user.save({ validateBeforeSave: false });

    throw new AppError('Error sending email. Please try again later.', 500);
  }
});

import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';
import { User } from '../models/User';
import { AppError } from '../utils/AppError';
import { catchAsync } from '../utils/catchAsync';

interface JwtPayload {
  id: string;
  iat: number;
  exp: number;
}

// Extend Request interface to include user property
declare global {
  namespace Express {
    interface Request {
      user?: any;
    }
  }
}

export const protect = catchAsync(async (req: Request, res: Response, next: NextFunction) => {
  // 1) Get token and check if it's there
  let token;
  if (req.headers.authorization && req.headers.authorization.startsWith('Bearer')) {
    token = req.headers.authorization.split(' ')[1];
  } else if (req.cookies.jwt) {
    token = req.cookies.jwt;
  }

  if (!token) {
    throw new AppError('You are not logged in! Please log in to get access.', 401);
  }

  // 2) Verify token
  const decoded = jwt.verify(token, process.env.JWT_SECRET!) as JwtPayload;

  // 3) Check if user still exists
  const currentUser = await User.findById(decoded.id);
  if (!currentUser) {
    throw new AppError('The user belonging to this token no longer exists.', 401);
  }

  // 4) Check if user changed password after the token was issued
  if (currentUser.changedPasswordAfter(decoded.iat)) {
    throw new AppError('User recently changed password! Please log in again.', 401);
  }

  // 5) Check if user account is active
  if (!currentUser.active) {
    throw new AppError('Your account has been deactivated. Please contact support.', 401);
  }

  // Grant access to protected route
  req.user = currentUser;
  next();
});

export const restrictTo = (...roles: string[]) => {
  return (req: Request, res: Response, next: NextFunction) => {
    if (!roles.includes(req.user.role)) {
      throw new AppError('You do not have permission to perform this action', 403);
    }
    next();
  };
};

export const isLoggedIn = async (req: Request, res: Response, next: NextFunction) => {
  try {
    // 1) Get token
    let token;
    if (req.headers.authorization && req.headers.authorization.startsWith('Bearer')) {
      token = req.headers.authorization.split(' ')[1];
    } else if (req.cookies.jwt) {
      token = req.cookies.jwt;
    }

    if (!token) {
      return next();
    }

    // 2) Verify token
    const decoded = jwt.verify(token, process.env.JWT_SECRET!) as JwtPayload;

    // 3) Check if user still exists
    const currentUser = await User.findById(decoded.id);
    if (!currentUser) {
      return next();
    }

    // 4) Check if user changed password after the token was issued
    if (currentUser.changedPasswordAfter(decoded.iat)) {
      return next();
    }

    // 5) Check if user account is active
    if (!currentUser.active) {
      return next();
    }

    // There is a logged in user
    req.user = currentUser;
    return next();
  } catch (error) {
    return next();
  }
};

export const apiKeyAuth = catchAsync(async (req: Request, res: Response, next: NextFunction) => {
  const apiKey = req.headers['x-api-key'] as string;

  if (!apiKey) {
    throw new AppError('API key is required', 401);
  }

  // In a real application, you would validate the API key against your database
  // For this example, we'll check against environment variables
  const validApiKeys = process.env.VALID_API_KEYS?.split(',') || [];

  if (!validApiKeys.includes(apiKey)) {
    throw new AppError('Invalid API key', 401);
  }

  next();
});

export const rateLimitByUser = catchAsync(async (req: Request, res: Response, next: NextFunction) => {
  if (!req.user) {
    throw new AppError('User authentication required for rate limiting', 401);
  }

  const userId = req.user._id.toString();
  const now = Date.now();
  const windowMs = 15 * 60 * 1000; // 15 minutes
  const maxRequests = req.user.role === 'premium' ? 1000 : 100;

  // In a real application, you would use Redis or another fast storage solution
  // This is a simplified example using memory (not suitable for production with multiple servers)
  if (!global.userRateLimits) {
    global.userRateLimits = new Map();
  }

  const userLimits = global.userRateLimits.get(userId) || { count: 0, resetTime: now + windowMs };

  if (now > userLimits.resetTime) {
    userLimits.count = 1;
    userLimits.resetTime = now + windowMs;
  } else {
    userLimits.count++;
  }

  global.userRateLimits.set(userId, userLimits);

  if (userLimits.count > maxRequests) {
    throw new AppError('Too many requests, please try again later', 429);
  }

  // Add rate limit headers
  res.set({
    'X-RateLimit-Limit': maxRequests.toString(),
    'X-RateLimit-Remaining': Math.max(0, maxRequests - userLimits.count).toString(),
    'X-RateLimit-Reset': new Date(userLimits.resetTime).toISOString(),
  });

  next();
});

import express from 'express';
import rateLimit from 'express-rate-limit';
import helmet from 'helmet';
import mongoSanitize from 'express-mongo-sanitize';
import xss from 'xss-clean';
import hpp from 'hpp';
import cors from 'cors';
import compression from 'compression';

import { protect, restrictTo, apiKeyAuth } from '../middleware/auth';
import { errorHandler } from '../middleware/errorHandler';
import { requestLogger } from '../middleware/logger';

// Import route handlers
import authRoutes from './auth';
import userRoutes from './users';
import postRoutes from './posts';
import uploadRoutes from './upload';
import analyticsRoutes from './analytics';

const router = express.Router();

// Security middleware
router.use(helmet());

// CORS configuration
router.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-API-Key'],
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

router.use('/api/v1/', limiter);

// Body parsing and sanitization
router.use(express.json({ limit: '10mb' }));
router.use(express.urlencoded({ extended: true, limit: '10mb' }));
router.use(mongoSanitize());
router.use(xss());
router.use(hpp({
  whitelist: ['sort', 'fields', 'page', 'limit'],
}));

// Compression
router.use(compression());

// Request logging
router.use(requestLogger);

// API versioning
const v1Router = express.Router();

// Health check endpoint
v1Router.get('/health', (req, res) => {
  res.status(200).json({
    status: 'success',
    message: 'API is running',
    timestamp: new Date().toISOString(),
    version: process.env.API_VERSION || '1.0.0',
  });
});

// API documentation endpoint
v1Router.get('/docs', (req, res) => {
  res.status(200).json({
    status: 'success',
    message: 'API Documentation',
    version: '1.0.0',
    endpoints: {
      auth: {
        'POST /auth/signup': 'Register a new user',
        'POST /auth/login': 'Login user',
        'POST /auth/logout': 'Logout user',
        'POST /auth/forgot-password': 'Send password reset email',
        'PATCH /auth/reset-password/:token': 'Reset password with token',
        'PATCH /auth/update-password': 'Update current user password',
      },
      users: {
        'GET /users': 'Get all users (admin only)',
        'GET /users/me': 'Get current user profile',
        'PATCH /users/me': 'Update current user profile',
        'DELETE /users/me': 'Deactivate current user account',
        'GET /users/:id': 'Get user by ID',
      },
      posts: {
        'GET /posts': 'Get all posts',
        'POST /posts': 'Create new post',
        'GET /posts/:id': 'Get post by ID',
        'PATCH /posts/:id': 'Update post',
        'DELETE /posts/:id': 'Delete post',
      },
      upload: {
        'POST /upload/image': 'Upload image file',
        'POST /upload/video': 'Upload video file',
        'DELETE /upload/:fileId': 'Delete uploaded file',
      },
      analytics: {
        'GET /analytics/dashboard': 'Get dashboard analytics',
        'GET /analytics/users': 'Get user analytics',
        'GET /analytics/posts': 'Get post analytics',
      },
    },
  });
});

// Authentication routes (public)
v1Router.use('/auth', authRoutes);

// Protected routes
v1Router.use('/users', protect, userRoutes);
v1Router.use('/posts', protect, postRoutes);
v1Router.use('/upload', protect, uploadRoutes);

// Admin only routes
v1Router.use('/analytics', protect, restrictTo('admin', 'moderator'), analyticsRoutes);

// API key protected routes (for external integrations)
const externalRouter = express.Router();
externalRouter.use(apiKeyAuth);
externalRouter.get('/public-posts', (req, res) => {
  res.status(200).json({
    status: 'success',
    message: 'Public posts endpoint for external integrations',
  });
});

v1Router.use('/external', externalRouter);

// Mount v1 router
router.use('/api/v1', v1Router);

// Catch all unhandled routes
router.all('*', (req, res) => {
  res.status(404).json({
    status: 'fail',
    message: `Route ${req.originalUrl} not found`,
  });
});

// Global error handler
router.use(errorHandler);

export default router;
